using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;
class FuelTests {static void Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{foreach(string d in new[]{args[0],Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)}){string f=Path.Combine(d,new AssemblyName(e.Name).Name+".dll");if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};Run();}
[MethodImpl(MethodImplOptions.NoInlining)]static void Run(){new Checks().Run();}}
class Checks {
void Check(bool pass,string text){if(!pass)throw new Exception("FAIL "+text);Console.WriteLine("PASS "+text);}
Groundworks.FuelFire.FuelReservoir Tank(double fill,bool ox,bool inert){var r=new Groundworks.FuelFire.FuelReservoir();r.slots.Add(new Groundworks.FuelFire.FluidSlot{name="fuel",profile=new Groundworks.FuelFire.FuelProfile{name="fuel",kind=inert?Groundworks.FuelFire.FluidKind.Inert:Groundworks.FuelFire.FluidKind.Fuel},amount=100*fill,capacity=100,density=.005});if(ox)r.slots.Add(new Groundworks.FuelFire.FluidSlot{name="ox",profile=new Groundworks.FuelFire.FuelProfile{name="ox",kind=Groundworks.FuelFire.FluidKind.Oxidizer},amount=100*fill,capacity=100,density=.005});return r;}
public void Run(){var empty=Tank(0,false,false);empty.Step(.1,1,true,true,false);Check(empty.LastLeakKgS==0&&empty.LastBurnKgS==0&&!empty.Burning,"fresh empty tank cannot leak or burn");var full=Tank(1,false,false);var low=Tank(.1,false,false);full.Step(.1,.7,true,false,false);low.Step(.1,.7,true,false,false);Check(full.LastLeakKgS>low.LastLeakKgS&&low.LastLeakKgS>0,"fill-dependent leakage rate");Check(!full.Burning&&full.BurnedFuelKg==0,"cold unignited fuel only leaks");full.Step(.1,.7,true,true,false);low.Step(.1,.7,true,true,false);Check(full.LastBurnKgS>low.LastBurnKgS&&low.LastBurnKgS>0,"burn intensity follows actual released fuel mass");Check(Groundworks.FuelFire.FuelReservoir.VisualScale(full.LastBurnKgS)>Groundworks.FuelFire.FuelReservoir.VisualScale(low.LastBurnKgS),"visual fire scale is monotonic with burn rate");var vacuum=Tank(1,false,false);vacuum.Step(.1,.7,false,true,false);Check(!vacuum.Burning&&vacuum.LastBurnKgS==0,"fuel without oxygen supply does not burn in vacuum");var mixed=Tank(1,true,false);mixed.Step(.1,.7,false,true,false);Check(mixed.Burning&&mixed.BurnedOxKg>0,"stored oxidizer supports the abstract vacuum reaction");var water=Tank(1,false,true);water.Step(.1,1,true,true,false);Check(water.LastLeakKgS>0&&!water.Burning,"inert liquid never ignites");var finite=Tank(.1,true,false);double start=finite.LiquidRemainingKg;for(int i=0;i<8000;i++)finite.Step(.05,1,false,true,false);double accounted=finite.LiquidRemainingKg+finite.CloudKg+finite.BurnedFuelKg+finite.BurnedOxKg+finite.DispersedKg;Check(Math.Abs(start-accounted)<1e-7,"fluid mass ledger closes without creating fuel");Check(finite.LiquidRemainingKg<1e-8&&!finite.Burning&&finite.LastBurnKgS==0,"finite supply exhausts and fire extinguishes");var fine=Tank(1,false,false);var coarse=Tank(1,false,false);for(int i=0;i<500;i++)fine.Step(.02,.5,true,false,false);for(int i=0;i<100;i++)coarse.Step(.1,.5,true,false,false);Check(Math.Abs(fine.LiquidRemainingKg-coarse.LiquidRemainingKg)<.01*fine.LiquidRemainingKg,"leakage agrees across representative fixed timesteps");Console.WriteLine("FUEL MODEL CHECKS COMPLETE");}}
